CREATE TABLE IF NOT EXISTS security_reviews (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, package_hash VARCHAR(128) NOT NULL, provider VARCHAR(64) NOT NULL, model VARCHAR(191) NOT NULL, summary TEXT NOT NULL, findings LONGTEXT NOT NULL, recommendation TEXT NOT NULL, outdated BOOLEAN NOT NULL DEFAULT FALSE, reviewed_at VARCHAR(40) NOT NULL, KEY idx_security_reviews_skill_time(skill_id,reviewed_at), FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE) ENGINE=InnoDB;
